package org.familyhealthcare.service;
import org.familyhealthcare.entity.NotificationChannel;
import org.familyhealthcare.mapper.NotificationChannelMapper;
import org.familyhealthcare.service.careplan.CarePlanNotificationTransport.*;
import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import org.springframework.http.*;
import org.springframework.web.client.*;
import java.net.InetAddress;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** All DNS and HTTP are synthetic. Never reads configured channels or reaches the network. */
class AlertWorkflowNotificationTransportTest {
    NotificationDeliveryService service;NotificationChannel channel;Fake transport;
    @BeforeEach void setup() throws Exception {transport=new Fake();service=new NotificationDeliveryService(new WebhookTargetPolicy(host->new InetAddress[]{InetAddress.getByAddress(new byte[]{8,8,8,8})}),transport);NotificationChannelMapper mapper=mock(NotificationChannelMapper.class);channel=new NotificationChannel();channel.setId(1L);channel.setUserId(1L);channel.setEnabled(1);channel.setChannelType("WEBHOOK");channel.setWebhookUrl("https://fake.invalid/provider?token=synthetic");when(mapper.selectById(1L)).thenReturn(channel);ReflectionTestUtils.setField(service,"mapper",mapper);ReflectionTestUtils.setField(service,"robots",mock(RobotChannelConfigService.class));}
    DeliveryAttempt attempt(){return service.deliverAlertWorkflowAttempt(1,1,"ALERT_WORKFLOW_SOURCE_CHANGED","PRIVATE Patient glucose 18 note","/alert-workflows/12");}
    @Test void genericEnglishAndChineseDiscardClinicalTextAndUnsafePaths(){assertEquals(DeliveryOutcome.DELIVERED,attempt().getOutcome());assertEquals("Measurement follow-up update",transport.body.get("title"));assertEquals("Open your measurement follow-up after signing in. /alert-workflows/12",transport.body.get("content"));UserLanguagePreferenceService language=mock(UserLanguagePreferenceService.class);when(language.get(1L)).thenReturn("zh-CN");ReflectionTestUtils.setField(service,"languagePreference",language);attempt();assertEquals("测量跟进更新",transport.body.get("title"));assertFalse(transport.body.toString().contains("PRIVATE"));service.deliverAlertWorkflowAttempt(1,1,"ALERT_WORKFLOW_DUE","secret","https://patient.invalid?id=secret");assertEquals("请登录后查看测量跟进。 /alert-workflows",transport.body.get("content"));}
    @Test void channelOwnershipReloadMustStillMatchExpectedRecipient(){channel.setUserId(6L);assertEquals(DeliveryOutcome.NO_CHANNEL,attempt().getOutcome());assertEquals(0,transport.calls);}
    @Test void safeOutcomesPreserveExplicitRetryabilityAndUnknown(){for(int status:new int[]{400,403,408,429,500,503}){transport.error=HttpClientErrorException.create(HttpStatus.valueOf(status),"private",HttpHeaders.EMPTY,"token=secret".getBytes(),java.nio.charset.StandardCharsets.UTF_8);DeliveryAttempt out=attempt();assertEquals(status==408||status>=500?DeliveryOutcome.UNKNOWN:DeliveryOutcome.FAILED,out.getOutcome());assertEquals(status==429,out.isRetryable());}HttpHeaders headers=new HttpHeaders();headers.add("Retry-After","30");transport.error=HttpClientErrorException.create(HttpStatus.TOO_MANY_REQUESTS,"private",headers,new byte[0],java.nio.charset.StandardCharsets.UTF_8);assertFalse(attempt().isRetryable());transport.error=new ResourceAccessException("secret url/token");assertEquals(DeliveryOutcome.UNKNOWN,attempt().getOutcome());}
    @Test void providerAcknowledgementMustBeExplicitAndNeverMeansRead(){channel.setChannelType("WECHAT_WEBHOOK");transport.response=ResponseEntity.ok("{\"errcode\":0}");assertEquals(DeliveryOutcome.DELIVERED,attempt().getOutcome());transport.response=ResponseEntity.ok("{\"errcode\":1,\"errmsg\":\"token=secret\"}");assertEquals(DeliveryOutcome.FAILED,attempt().getOutcome());for(String body:new String[]{"{}","{\"errcode\":0.0}","not-json","{\"errcode\":0,\"errcode\":1}"}){transport.response=ResponseEntity.ok(body);assertEquals(DeliveryOutcome.UNKNOWN,attempt().getOutcome());}}
    @Test void robotKeywordDoesNotAddPrivateConfigurationText(){channel.setChannelType("DINGTALK_WEBHOOK");channel.setRobotKeyword("PRIVATE keyword");transport.response=ResponseEntity.ok("{\"errcode\":0}");assertEquals(DeliveryOutcome.DELIVERED,attempt().getOutcome());assertFalse(transport.body.toString().contains("PRIVATE"));}
    @Test void missingDisabledInvalidDomainAndInvalidConfigurationFailWithoutNetwork(){channel.setEnabled(0);assertEquals(DeliveryOutcome.NO_CHANNEL,attempt().getOutcome());channel.setEnabled(1);assertEquals(DeliveryOutcome.FAILED,service.deliverCarePlanAttempt(1,"ALERT_WORKFLOW_CREATED","title","/alert-workflows/1").getOutcome());assertEquals(DeliveryOutcome.FAILED,service.deliverAlertWorkflowAttempt(1,1,"CARE_PLAN_CREATED","title","/care-plans/1").getOutcome());channel.setWebhookUrl("http://fake.invalid");assertEquals(DeliveryOutcome.FAILED,attempt().getOutcome());assertEquals(0,transport.calls);}
    @Test void existingCarePlanTransportAndGenericLocalizationRemainIntact(){assertEquals(DeliveryOutcome.DELIVERED,service.deliverCarePlanAttempt(1,"CARE_PLAN_PLAN_PUBLISHED","PRIVATE","/care-plans/9").getOutcome());assertEquals("Care plan update",transport.body.get("title"));assertEquals("Open your care plan after signing in. /care-plans/9",transport.body.get("content"));}
    static class Fake extends WebhookTransport {int calls;Map<String,Object> body;RuntimeException error;ResponseEntity<String> response=ResponseEntity.ok("{}");@Override public ResponseEntity<String> post(WebhookTargetPolicy.Target target,Map<String,Object> body){calls++;this.body=body;if(error!=null)throw error;return response;}}
}
